package cc.ataglace.molebutter.marketplace.api;
import java.util.*;
import tools.jackson.databind.ObjectMapper;
import static cc.ataglace.molebutter.marketplace.api.PartnerFormSupport.*;
/** Native coded attributes and per-item media; keys are app option UUIDs, never external IDs. */
public record LotteonInput(PartnerEditor.Input product,List<Attribute> attributes,Map<String,Item> items,String representativeOptionId,Map<String,String> status,Map<String,String> deliveryIntent) {
 public LotteonInput(PartnerEditor.Input product,List<Attribute> attributes,Map<String,Item> items,String representativeOptionId,Map<String,String> status){this(product,attributes,items,representativeOptionId,status,Map.of());}
 public LotteonInput(PartnerEditor.Input product,List<Attribute> attributes,Map<String,Item> items,String representativeOptionId){this(product,attributes,items,representativeOptionId,Map.of());}
 public record Attribute(String code,String name,String valueCode,String value) {}
 public record Picture(PartnerEditor.Image image,String type) {}
 public record Item(List<Attribute> attributes,List<Picture> images) {}
 public static LotteonInput structure(LotteonInput input){
  if(input==null)return null;var p=PartnerFormSupport.structure(input.product());var attrs=attributes(input.attributes());var items=new LinkedHashMap<String,Item>();
  if(input.items()!=null){if(input.items().size()>500)throw invalid("롯데ON 단품은 500개 이하로 조회합니다.");for(var e:input.items().entrySet()){
   String id=MarketplaceDocuments.uuid(e.getKey());if(p.options().stream().noneMatch(o->o.id().equals(id)))throw invalid("이미지·속성의 단품 연결을 확인해 주세요.");var pictures=new ArrayList<Picture>();var row=e.getValue();
   for(var v:MarketplaceDocuments.list(row.images(),10)){if(!Set.of("IMG_SQRE","IMG_LNTH").contains(v.type()))throw invalid("이미지 유형을 선택해 주세요.");pictures.add(new Picture(v.image(),v.type()));}
   var normalized=PartnerFormSupport.structure(new PartnerEditor.Input(Map.of(),List.of(),pictures.stream().map(Picture::image).toList(),"","",List.of(),List.of()));
   var safe=new ArrayList<Picture>();for(int n=0;n<pictures.size();n++)safe.add(new Picture(normalized.images().get(n),pictures.get(n).type()));
   items.put(id,new Item(attributes(row.attributes()),List.copyOf(safe)));
  }}
  var status=new LinkedHashMap<String,String>();for(String key:List.of("slStatCd","slStatRsnCd","pdAprvReqCd","pdAprvReqGvbkRsnCd","catAprvStatCd","catGvbkRsnCd","catGvbkRsnCnts","pdInfoAprvStatCd","pdInfoGvbkRsnCd","pdInfoGvbkRsnCnts","fnlAprvYn"))if(input.status()!=null&&input.status().get(key)!=null)status.put(key,MarketplaceDocuments.text(input.status().get(key),4000));return new LotteonInput(p,attrs,Map.copyOf(items),input.representativeOptionId()==null?null:MarketplaceDocuments.uuid(input.representativeOptionId()),Map.copyOf(status),input.deliveryIntent()==null?null:deliveryIntent(input.deliveryIntent()));
 }
 public static Map<String,String> deliveryIntent(Map<String,String> values){var out=new LinkedHashMap<String,String>();if(values!=null){if(values.size()>7)throw invalid("공통 배송비 비교 항목을 확인해 주세요.");for(var e:values.entrySet()){if(!Set.of("chargeType","charge","freeOver","returnCharge","initialReturnCharge","jejuCharge","remoteCharge").contains(e.getKey()))throw invalid("공통 배송비 비교 항목을 확인해 주세요.");out.put(e.getKey(),MarketplaceDocuments.text(e.getValue(),100));}}return Map.copyOf(out);}
 public static Map<String,String> commonDelivery(MarketplaceDrafts.Document d){var v=d.delivery();var out=new LinkedHashMap<String,String>();for(var e:Map.of("chargeType",Objects.toString(v.chargeType(),""),"charge",Objects.toString(v.charge(),""),"freeOver",Objects.toString(v.freeOver(),""),"returnCharge",Objects.toString(v.returnCharge(),""),"initialReturnCharge",Objects.toString(v.initialReturnCharge(),""),"jejuCharge",Objects.toString(v.jejuCharge(),""),"remoteCharge",Objects.toString(v.remoteCharge(),"")).entrySet())if(!e.getValue().isBlank())out.put(e.getKey(),e.getValue());return Map.copyOf(out);}
 private static List<Attribute> attributes(List<Attribute> input){var out=new ArrayList<Attribute>();var seen=new HashSet<String>();for(var a:MarketplaceDocuments.list(input,50)){String code=MarketplaceDocuments.text(a.code(),20);if(!code.matches("[A-Za-z0-9_]{1,20}")||!seen.add(code))throw invalid("속성 코드를 다시 선택해 주세요.");out.add(new Attribute(code,MarketplaceDocuments.text(a.name(),255),MarketplaceDocuments.text(a.valueCode(),20),MarketplaceDocuments.text(a.value(),255)));}return List.copyOf(out);}
 public static LotteonInput from(PartnerEditor.Input p){return p==null?null:new LotteonInput(p,List.of(),Map.of(),p.options().isEmpty()?null:p.options().getFirst().id());}
 public static LotteonInput get(MarketplaceDrafts.Document d){var c=d.markets().get(MarketplaceDrafts.Market.LOTTEON);return c==null||c.lotteon()==null?null:c.lotteon().nativeInput()==null?from(c.lotteon().editorInput()):c.lotteon().nativeInput();}
 public static MarketplaceDrafts.Document with(MarketplaceDrafts.Document d,LotteonInput i,MarketplaceDrafts.EditorState state){
  d=PartnerFormSupport.withInput(d,"LOTTEON",i.product());var map=new EnumMap<MarketplaceDrafts.Market,MarketplaceDrafts.MarketConfig>(MarketplaceDrafts.Market.class);map.putAll(d.markets());var m=map.get(MarketplaceDrafts.Market.LOTTEON);map.put(MarketplaceDrafts.Market.LOTTEON,new MarketplaceDrafts.MarketConfig(m.categoryCode(),m.overrides(),m.coupang(),m.naver(),m.esm(),new MarketplaceDrafts.Lotteon(m.lotteon().brandId(),i.product(),state,i),m.addressBook(),m.elevenst()));return new MarketplaceDrafts.Document(d.id(),d.revision(),d.common(),d.options(),d.stockMode(),d.productQuantity(),d.services(),d.media(),d.delivery(),d.selectedMarkets(),Map.copyOf(map));
 }
 public static Map<String,Object> parts(LotteonInput i){var out=new LinkedHashMap<String,Object>();PartnerFormSupport.parts(i.product()).forEach((k,v)->out.put("product."+k,v));for(var o:i.product().options()){String k="product.options."+o.id()+".";out.put(k+"name",o.name());out.put(k+"sku",o.sku());out.put(k+"price",o.price());out.put(k+"quantity",o.quantity());out.put(k+"attributes",o.attributes());out.put(k+"usable",o.usable());}out.put("deliveryIntent",i.deliveryIntent()==null?Map.of():i.deliveryIntent());out.put("attributes",i.attributes());i.items().forEach((id,item)->{out.put("items."+id+".attributes",item.attributes());out.put("items."+id+".images",item.images());});out.put("representativeOptionId",i.representativeOptionId());return out;}
 public static LotteonInput apply(LotteonInput i,List<MarketplaceEditing.Change> changes,ObjectMapper json){var node=json.valueToTree(i);var seen=new HashSet<String>();for(var c:MarketplaceDocuments.list(changes,500)){if(c.optionId()!=null||c.path()==null||!c.path().startsWith("lotteon.")||!seen.add(c.path()))throw invalid("롯데ON 변경 항목을 확인해 주세요.");String key=c.path().substring(8);if(!parts(i).containsKey(key)&&!key.startsWith("product.fields.")&&!key.matches("items\\.[a-fA-F0-9-]{36}\\.(attributes|images)"))throw invalid("지원하지 않는 롯데ON 변경 항목입니다.");if(key.startsWith("product.fields.")){((tools.jackson.databind.node.ObjectNode)node.path("product").path("fields")).set(key.substring(15),json.valueToTree(c.value()));continue;}if(key.startsWith("product.options.")){String[] option=key.split("\\.");if(option.length!=4)throw invalid("옵션 변경 경로를 확인해 주세요.");var rows=node.path("product").path("options");boolean found=false;for(var row:rows)if(option[2].equals(row.path("id").asString())){((tools.jackson.databind.node.ObjectNode)row).set(option[3],json.valueToTree(c.value()));found=true;break;}if(!found)throw invalid("옵션 연결을 확인해 주세요.");continue;}var path=key.split("\\.");var current=(tools.jackson.databind.node.ObjectNode)node;for(int n=0;n<path.length-1;n++){if(current.path(path[n]).isMissingNode())current.set(path[n],json.createObjectNode());current=(tools.jackson.databind.node.ObjectNode)current.path(path[n]);}current.set(path[path.length-1],json.valueToTree(c.value()));}return structure(json.treeToValue(node,LotteonInput.class));}
 public static List<MarketplaceEditing.Change> diff(LotteonInput a,LotteonInput b,ObjectMapper json){var before=parts(a);var after=parts(b);var keys=new LinkedHashSet<>(before.keySet());keys.addAll(after.keySet());boolean same=a.product().options().stream().map(PartnerEditor.Option::id).toList().equals(b.product().options().stream().map(PartnerEditor.Option::id).toList());return keys.stream().filter(k->same?!k.equals("product.options"):!k.startsWith("product.options.")).filter(k->!Objects.equals(json.valueToTree(before.get(k)),json.valueToTree(after.get(k)))).map(k->new MarketplaceEditing.Change("lotteon."+k,null,after.get(k))).toList();}
 public static MarketplaceEditing.PendingRebase rebase(LotteonInput a,LotteonInput b,List<MarketplaceEditing.Change> changes,ObjectMapper json){var desired=parts(apply(a,changes,json));var before=parts(a);var now=parts(b);var pending=new ArrayList<MarketplaceEditing.Change>();var conflicts=new ArrayList<MarketplaceEditing.Conflict>();for(var c:changes){String k=c.path().substring(8);if(Objects.equals(json.valueToTree(now.get(k)),json.valueToTree(desired.get(k))))continue;pending.add(c);if(!Objects.equals(json.valueToTree(before.get(k)),json.valueToTree(now.get(k))))conflicts.add(new MarketplaceEditing.Conflict(c.path(),null,before.get(k),now.get(k),desired.get(k)));}return new MarketplaceEditing.PendingRebase(pending,conflicts);}
}
